'use client' 

import { createClient } from '@/utils/supabase/client'
import { useRouter } from 'next/navigation'
import { useState, useEffect, useMemo } from 'react'
import { User } from '@supabase/supabase-js'
import React from 'react' 
import { pullReportAction } from './actions' 
import Link from 'next/link'

type Report = {
  id: string;
  status: string;
  notes: string | null;
  report_explanation: string | null; 
  submitted_by: string;
  subject_cadet_id: string;
  current_approver_group_id: string | null; 
  date_of_offense: string;
  offense_type_id: string;
  demerits_effective: number;
  linked_incident_id: string | null;
  subject: { first_name: string, last_name: string }; 
  submitter: { first_name: string, last_name: string };
  offense_type: {
    offense_name: string;
    offense_code: string;
    demerits: number;
    policy_category: number;
  }
};

type Log = {
  id: string;
  action: string;
  comment: string;
  created_at: string;
  actor: { first_name: string, last_name: string } | null; 
};

type OffenseType = {
  id: string;
  offense_group: string;
  offense_name: string;
  demerits: number;
}

type Appeal = {
  id: string;
  status: string;
  justification: string;
  current_assignee_id: string | null;
  current_group_id: string | null;
  issuer_comment: string | null;
  chain_comment: string | null;
  final_comment: string | null;
}

export default function ReportDetailsClient({
  user,
  initialReport,
  initialLogs,
  initialAppeal,
  offenses,
  escalationTarget,
  permissions,
  linkedIncidentId,
  isStaff,
  canViewNarrative 
}: {
  user: User
  initialReport: Report
  initialLogs: Log[]
  initialAppeal: Appeal | null
  offenses: any[]
  escalationTarget: string | null
  permissions: { isSubmitter: boolean, isSubject: boolean, isApprover: boolean, canActOnAppeal: boolean, canPull: boolean }
  linkedIncidentId: string | null
  isStaff: boolean
  canViewNarrative: boolean
}) {
  const router = useRouter()
  const supabase = createClient()
  
  const [report, setReport] = useState<Report>(initialReport)
  const [logs, setLogs] = useState<Log[]>(initialLogs)
  const [appeal, setAppeal] = useState<Appeal | null>(initialAppeal)

  // Forms
  const [actionComment, setActionComment] = useState('')
  const [appealText, setAppealText] = useState('')
  const [isProcessing, setIsProcessing] = useState(false)
  const [selectedOffenseId, setSelectedOffenseId] = useState(report.offense_type_id)

  // Pull Modal
  const [isPullModalOpen, setIsPullModalOpen] = useState(false)
  const [pullComment, setPullComment] = useState('')
  const [isActionLoading, setIsActionLoading] = useState(false)

  // --- ACTIONS ---

  const handleApprove = async () => {
    setIsProcessing(true)
    const { error } = await supabase.rpc('approve_report', { p_report_id: report.id, p_comment: actionComment })
    if (error) alert(error.message)
    else router.refresh()
    setIsProcessing(false)
  }

  const handleReject = async () => {
    setIsProcessing(true)
    const { error } = await supabase.rpc('reject_report', { p_report_id: report.id, p_comment: actionComment })
    if (error) alert(error.message)
    else router.refresh()
    setIsProcessing(false)
  }

  const handleSubmitAppeal = async () => {
      setIsProcessing(true)
      const { error } = await supabase.rpc('start_appeal', { p_report_id: report.id, p_justification: appealText })
      if (error) alert(error.message)
      else router.refresh()
      setIsProcessing(false)
  }

  const handleProcessAppeal = async (verdict: 'uphold' | 'reject' | 'escalate') => {
      setIsProcessing(true)
      let fn = ''
      const payload: any = { p_appeal_id: appeal?.id, p_comment: actionComment }
      
      if (verdict === 'uphold') { 
          fn = 'resolve_appeal_uphold' 
      } else if (verdict === 'reject') { 
          fn = 'resolve_appeal_reject' 
      } else if (verdict === 'escalate') {
          fn = 'escalate_appeal';
          payload.p_next_group_id = escalationTarget; 
      }

      const { error } = await supabase.rpc(fn, payload)
      if (error) alert(error.message)
      else router.refresh()
      setIsProcessing(false)
  }

  const handleResubmit = async () => {
      setIsProcessing(true)
      const { error } = await supabase.rpc('update_report_revision', { 
          p_report_id: report.id, 
          p_new_offense_id: selectedOffenseId,
          p_new_notes: actionComment 
      })
      if (error) alert(error.message)
      else router.refresh()
      setIsProcessing(false)
  }

  const handlePullReport = async () => {
    setIsActionLoading(true)
    const result = await pullReportAction(report.id, pullComment)
    if (result.error) alert(result.error)
    else {
        setIsPullModalOpen(false)
        router.refresh()
    }
    setIsActionLoading(false)
  }

  // --- RENDER HELPERS ---

  const StatusBadge = ({ status }: { status: string }) => {
    const styles = {
      pending_approval: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-200',
      needs_revision: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-200',
      completed: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-200',
      rejected: 'bg-destructive/10 text-destructive',
      pulled: 'bg-muted text-muted-foreground',
      appealed: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-200'
    }[status] || 'bg-muted text-muted-foreground'
    
    return <span className={`px-2 py-1 rounded-full text-xs font-bold uppercase ${styles}`}>{status.replace('_', ' ')}</span>
  }

  return (
    <div className="max-w-5xl mx-auto p-4 sm:p-6 lg:p-8 animate-in fade-in duration-500">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
           {/* UPDATED: Uses primary color for title */}
           <h1 className="text-3xl font-bold text-primary">Report #{report.id.slice(0,6)}</h1>
           <p className="text-muted-foreground flex items-center gap-2 mt-1">
             Filed on {new Date(report.created_at).toLocaleDateString()} by <span className="font-medium text-foreground">{report.submitter.last_name}</span>
           </p>
           {/* Linked Incident Badge */}
           {linkedIncidentId && (
              <div className="mt-2 inline-flex items-center gap-2 bg-muted/50 px-3 py-1 rounded border border-border">
                  <span className="text-xs font-bold text-muted-foreground uppercase">Linked Incident</span>
                  <Link href={`/incidents/${linkedIncidentId}`} className="text-xs text-primary hover:underline font-medium">
                      View Original Incident &rarr;
                  </Link>
              </div>
           )}
        </div>
        
        <div className="flex flex-col items-end gap-2">
            <StatusBadge status={report.status} />
            {permissions.canPull && (
                <button 
                  onClick={() => setIsPullModalOpen(true)} 
                  className="text-xs text-destructive hover:text-destructive/80 underline font-medium"
                >
                  Pull Report
                </button>
            )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        
        {/* --- LEFT: REPORT DETAILS --- */}
        <div className="lg:col-span-2 space-y-6">
            
            {/* MAIN CARD */}
            <div className="bg-card shadow-sm border border-border rounded-xl overflow-hidden">
                <div className="p-6 border-b border-border bg-muted/30 flex justify-between">
                    <div>
                        <h3 className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Subject</h3>
                        <p className="text-lg font-bold text-foreground">{report.subject.last_name}, {report.subject.first_name}</p>
                    </div>
                    <div className="text-right">
                        <h3 className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Demerits</h3>
                        <p className="text-2xl font-bold text-destructive">{report.offense_type.demerits}</p>
                    </div>
                </div>
                
                <div className="p-6 space-y-6">
                    <div>
                        <h3 className="text-xs font-bold text-muted-foreground uppercase mb-1">Offense</h3>
                        <p className="text-foreground font-medium">{report.offense_type.offense_name} ({report.offense_type.offense_code})</p>
                    </div>

                    {/* GREEN SHEET SUMMARY */}
                    <div>
                        <h3 className="text-xs font-bold text-muted-foreground uppercase mb-1">Summary (Green Sheet)</h3>
                        <div className="p-3 bg-muted/30 rounded-lg border border-border text-sm text-foreground">
                            {report.notes || "No notes provided."}
                        </div>
                    </div>

                    {/* NARRATIVE (CONDITIONAL) */}
                    {canViewNarrative && (
                        <div>
                            <h3 className="text-xs font-bold text-muted-foreground uppercase mb-1 flex items-center gap-2">
                                Full Narrative
                                {linkedIncidentId && <span className="text-[10px] bg-yellow-100 text-yellow-800 px-1 rounded border border-yellow-200">Staff Only</span>}
                            </h3>
                            <div className="p-3 bg-muted/30 rounded-lg border border-border text-sm text-foreground whitespace-pre-wrap">
                                {report.report_explanation || "No narrative provided."}
                            </div>
                        </div>
                    )}

                    {!canViewNarrative && (
                        <div className="p-4 border border-dashed border-border rounded bg-muted/10 text-center text-sm text-muted-foreground italic">
                            Full narrative is restricted to faculty for this report type.
                        </div>
                    )}
                </div>
            </div>

            {/* ACTION AREA */}
            {(permissions.isApprover || permissions.canActOnAppeal || (permissions.isSubmitter && report.status === 'needs_revision')) && (
                <div className="bg-card shadow-sm border border-border rounded-xl p-6">
                    <h3 className="text-lg font-bold text-foreground mb-4">Actions</h3>
                    
                    {/* 1. APPROVER ACTIONS */}
                    {permissions.isApprover && report.status === 'pending_approval' && (
                        <div className="space-y-4">
                            <textarea 
                                placeholder="Optional comments..." 
                                className="w-full border border-input rounded p-2 bg-background text-foreground" 
                                value={actionComment} 
                                onChange={e => setActionComment(e.target.value)} 
                            />
                            <div className="flex gap-3">
                                <button onClick={handleApprove} disabled={isProcessing} className="flex-1 bg-green-600 text-white py-2 rounded font-bold hover:bg-green-700 disabled:opacity-50">Approve</button>
                                <button onClick={handleReject} disabled={isProcessing} className="flex-1 bg-destructive text-destructive-foreground py-2 rounded font-bold hover:bg-destructive/90 disabled:opacity-50">Return for Revision</button>
                            </div>
                        </div>
                    )}

                    {/* 2. REVISION ACTIONS */}
                    {permissions.isSubmitter && report.status === 'needs_revision' && (
                        <div className="space-y-4">
                            <p className="text-sm text-destructive font-medium">This report was returned. Please update details below.</p>
                            
                            <div>
                                <label className="block text-xs font-bold text-muted-foreground mb-1">Update Offense</label>
                                <select 
                                    className="w-full border border-input rounded p-2 bg-background text-foreground" 
                                    value={selectedOffenseId} 
                                    onChange={e => setSelectedOffenseId(e.target.value)}
                                >
                                    {offenses.map((o: any) => <option key={o.id} value={o.id}>{o.offense_name}</option>)}
                                </select>
                            </div>

                            <textarea 
                                placeholder="Add revision notes..." 
                                className="w-full border border-input rounded p-2 bg-background text-foreground" 
                                value={actionComment} 
                                onChange={e => setActionComment(e.target.value)} 
                            />
                            
                            <button onClick={handleResubmit} disabled={isProcessing} className="w-full btn-primary font-bold py-2">Resubmit Report</button>
                        </div>
                    )}
                </div>
            )}
        </div>

        {/* --- RIGHT: HISTORY & APPEALS --- */}
        <div className="space-y-6">
            
            {/* APPEAL STATUS */}
            {permissions.isSubject && report.status === 'completed' && !appeal && (
                <div className="bg-card shadow-sm border border-border rounded-xl p-6">
                    <h3 className="text-lg font-bold text-foreground mb-2">Appeal Report</h3>
                    <p className="text-sm text-muted-foreground mb-4">You may appeal this report if you believe it was issued in error.</p>
                    <textarea 
                        className="w-full border border-input rounded p-2 mb-3 bg-background text-foreground" 
                        placeholder="Justification..." 
                        rows={3} 
                        value={appealText} 
                        onChange={e => setAppealText(e.target.value)} 
                    />
                    <button onClick={handleSubmitAppeal} disabled={!appealText || isProcessing} className="w-full btn-primary font-bold py-2">Submit Appeal</button>
                </div>
            )}

            {appeal && (
                <div className="bg-card shadow-sm border border-border rounded-xl overflow-hidden">
                    <div className="p-4 border-b border-border bg-purple-50 dark:bg-purple-900/20">
                        <h3 className="font-bold text-purple-900 dark:text-purple-100 flex items-center justify-between">
                            Appeal Active
                            <span className="text-xs bg-white dark:bg-black/20 px-2 py-1 rounded uppercase">{appeal.status.replace('_', ' ')}</span>
                        </h3>
                    </div>
                    <div className="p-4 space-y-4">
                        <div className="text-sm text-foreground italic border-l-2 border-purple-300 pl-3">"{appeal.justification}"</div>
                        
                        {/* Appeal Processing */}
                        {permissions.canActOnAppeal && (
                            <div className="pt-4 border-t border-border mt-2">
                                <p className="text-xs font-bold text-muted-foreground uppercase mb-2">Decision</p>
                                <textarea 
                                    className="w-full border border-input rounded p-2 text-sm mb-2 bg-background text-foreground" 
                                    placeholder="Reasoning..." 
                                    value={actionComment} 
                                    onChange={e => setActionComment(e.target.value)} 
                                />
                                <div className="flex flex-col gap-2">
                                    <button onClick={() => handleProcessAppeal('reject')} className="w-full bg-green-600 text-white py-1.5 rounded text-sm font-bold">Grant Appeal (Remove Demerits)</button>
                                    <button onClick={() => handleProcessAppeal('uphold')} className="w-full bg-destructive text-destructive-foreground py-1.5 rounded text-sm font-bold">Deny Appeal</button>
                                    {escalationTarget && (
                                        <button onClick={() => handleProcessAppeal('escalate')} className="w-full bg-muted text-foreground border border-input py-1.5 rounded text-sm font-bold hover:bg-accent">Escalate to Chain</button>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* LOGS */}
            <div className="bg-card shadow-sm border border-border rounded-xl overflow-hidden">
                <div className="p-4 border-b border-border bg-muted/30">
                    <h3 className="text-xs font-bold text-muted-foreground uppercase">Activity Log</h3>
                </div>
                <div className="divide-y divide-border max-h-96 overflow-y-auto">
                    {logs.map(log => (
                        <div key={log.id} className="p-3 text-sm hover:bg-muted/30 transition-colors">
                            <div className="flex justify-between text-xs text-muted-foreground mb-1">
                                <span>{new Date(log.created_at).toLocaleDateString()}</span>
                                <span className="font-medium text-foreground">{log.actor ? `${log.actor.last_name}` : 'System'}</span>
                            </div>
                            <p className="font-medium text-primary">{log.action.replace(/_/g, ' ')}</p>
                            {log.comment && <p className="text-muted-foreground mt-1 italic">"{log.comment}"</p>}
                        </div>
                    ))}
                    {logs.length === 0 && <div className="p-4 text-center text-muted-foreground text-sm italic">No activity recorded.</div>}
                </div>
            </div>
        </div>

      </div>

      {/* PULL MODAL */}
      {isPullModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm p-4">
          <div className="bg-card rounded-lg shadow-xl max-w-md w-full p-6 border border-border animate-in zoom-in-95 duration-200">
            <h3 className="text-lg font-bold text-foreground mb-2">Pull Report</h3>
            <p className="text-sm text-muted-foreground mb-4">
              This will effectively delete the report from the active record. It will remain in the database marked as "pulled" for audit purposes.
            </p>
            
            <div className="mb-4">
              <label htmlFor="pull_comment" className="block text-sm font-medium text-muted-foreground">
                Reason / Comment (Required)
              </label>
              <textarea
                id="pull_comment"
                rows={3}
                value={pullComment}
                onChange={(e) => setPullComment(e.target.value)}
                className="mt-1 block w-full rounded-md border-input bg-background text-foreground shadow-sm focus:border-primary focus:ring-primary sm:text-sm"
                placeholder="e.g., 'Pulled per discussion with cadet and issuer.'"
              />
            </div>
            
            <div className="mt-8 flex gap-4">
              <button
                type="button"
                onClick={() => setIsPullModalOpen(false)}
                disabled={isActionLoading}
                className="w-1/2 py-2 border border-input rounded-md text-foreground hover:bg-accent hover:text-accent-foreground"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handlePullReport}
                disabled={isActionLoading || !pullComment.trim()}
                className="w-1/2 py-2 bg-destructive text-destructive-foreground rounded-md hover:bg-destructive/90 disabled:opacity-50"
              >
                {isActionLoading ? 'Pulling...' : 'Confirm Pull'}
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  )
}